const docsPages = {
  home: { title:'Dokumentasi DECA', subtitle:'Panduan produk, operasional, dan integrasi untuk bisnis yang menerima atau menyalurkan pembayaran.', body:`<div class="content-section"><div class="section-label">MULAI DI SINI</div><h2>Pilih kebutuhan integrasi</h2><p>Dokumentasi DECA dibagi menurut tugas yang ingin diselesaikan. Mulai dari panduan produk untuk memahami alur bisnis, lalu buka API Reference untuk kontrak teknis.</p><div class="link-list">${row('Terima pembayaran','QRIS, Virtual Account, dan External Checkout.','docs/cash-in','ACCEPT PAYMENTS')} ${row('Kirim dana','Transfer bank, top up e-money, dan transaksi batch.','docs/cash-out','PAYOUTS')} ${row('Kelola saldo dan laporan','Inquiry saldo dan rekening koran melalui API.','docs/account','ACCOUNT')}</div></div><div class="content-section"><div class="section-label">INTEGRATION GUIDE</div><h2>Dari onboarding ke production</h2><ol class="plain-steps"><li>Bahas kebutuhan produk dan aktivasi merchant bersama tim DECA.</li><li>Pilih skema integrasi serta environment yang disediakan untuk akun merchant.</li><li>Bangun dan uji request, response, callback, serta pengecekan status.</li><li>Koordinasikan verifikasi dan aktivasi production dengan DECA.</li></ol>${linkRow('Mulai dengan onboarding merchant','docs/onboarding')} ${linkRow('Lihat checklist integrasi','docs/integration')}</div><div class="content-section"><div class="section-label">DOKUMENTASI TEKNIS</div><h2>API Reference</h2><p>Kontrak endpoint, header, schema request dan response, contoh payload, serta response code tersedia pada halaman API Reference.</p>${linkRow('Buka API Reference','reference/home')}</div><div class="content-section"><div class="section-label">BANTUAN</div><h2>Hubungi tim DECA</h2><p>Untuk akses, cakupan produk, credential, atau aktivasi environment, hubungi tim partnership.</p><a class="text-link" href="mailto:partnership@deca.co.id">partnership@deca.co.id ↗</a></div><div class="content-section"><div class="section-label">DOKUMENTASI DALAM PENYUSUNAN</div><h2>Panduan lainnya</h2>${comingSoonRow('Payment Link','Panduan dan ketentuan DECA belum tersedia.')} ${comingSoonRow('SDK & library','Paket resmi DECA belum tersedia.')} ${comingSoonRow('E-commerce plugins','Panduan integrasi plugin DECA belum tersedia.')} ${comingSoonRow('Wallet & sub-account','Cakupan layanan dan API DECA belum terverifikasi.')}</div>` },
  onboarding: { title:'Onboarding merchant', subtitle:'Mulai integrasi dengan mengonfirmasi kebutuhan bisnis dan akses bersama tim DECA.', body:`<p>Akses layanan dan credential diberikan melalui proses onboarding DECA. Form pendaftaran di website mengirim permintaan untuk ditindaklanjuti oleh tim; akun portal tidak dibuat otomatis.</p><div class="content-section"><h2>Ajukan kebutuhan bisnis</h2><ol class="plain-steps"><li>Hubungi <a href="mailto:partnership@deca.co.id">partnership@deca.co.id</a> dan sampaikan profil bisnis serta alur pembayaran yang dibutuhkan.</li><li>Tim DECA akan membantu mengarahkan proses verifikasi dan produk yang sesuai.</li><li>Setelah akses merchant disiapkan, tim akan menginformasikan cara memperoleh akses portal dan credential integrasi.</li></ol></div><div class="callout"><strong>Belum punya akses?</strong><p>Jangan gunakan credential contoh untuk transaksi nyata. Minta credential yang terikat ke merchant dan environment dari DECA.</p><a class="text-link" href="mailto:partnership@deca.co.id">Hubungi partnership DECA ↗</a></div>` },
  integration: { title:'Pilih metode integrasi', subtitle:'Tentukan alur produk, lalu implementasikan kontrak yang diberikan kepada merchant.', body:`<p>DECA menyediakan kontrak API untuk pembayaran masuk, pencairan dana, dan kebutuhan operasional. Cara implementasi bergantung pada produk yang diaktifkan untuk merchant.</p><div class="content-section"><h2>Alur implementasi</h2><ol class="plain-steps"><li>Pilih produk: QRIS, Virtual Account, External Checkout, transfer bank, top up e-money, atau layanan akun.</li><li>Pastikan protokol produk yang dipakai, yaitu SNAP atau Non-SNAP; keduanya memiliki skema credential dan signature berbeda.</li><li>Siapkan backend untuk menyimpan credential, membentuk request, menerima callback, dan mencocokkan status transaksi.</li><li>Implementasikan endpoint sesuai halaman API Reference. Periksa field wajib dan response code tiap endpoint.</li><li>Uji di environment yang dikonfirmasi DECA sebelum meminta aktivasi production.</li></ol></div><div class="content-section"><h2>Pilih alur produk</h2><div class="link-list">${row('Accept Payments','Pilih integrasi untuk QRIS, VA, atau External Checkout.','docs/cash-in')} ${row('Payouts','Pilih alur pengiriman dana ke bank atau e-money.','docs/cash-out')} ${row('API Reference','Lihat spesifikasi dan contoh teknis per endpoint.','reference/home')}</div></div><div class="callout"><strong>Credential dan key</strong><p>Simpan credential serta material signing di server. Jangan mengekspos secret di kode frontend, aplikasi pengguna, atau repository publik.</p></div>` },
  environments: { title:'Environment', subtitle:'Gunakan base URL serta credential yang sesuai dengan akses merchant.', body:`<p>DECA menyediakan endpoint staging untuk pengembangan dan endpoint production untuk transaksi merchant yang telah diaktifkan.</p><div class="table-wrap"><table class="param-table"><thead><tr><th>Environment</th><th>Base URL</th><th>Penggunaan</th></tr></thead><tbody><tr><td>Staging</td><td><code>https://api.dev.deca.co.id</code></td><td>Pengembangan dan pengujian</td></tr><tr><td>Production</td><td><code>https://api.deca.co.id</code></td><td>Transaksi production setelah aktivasi</td></tr></tbody></table></div><div class="callout"><strong>Akses merchant</strong><p>Credential dan ketersediaan produk dapat berbeda per environment. Konfirmasi ke DECA sebelum melakukan pengujian atau berpindah ke production.</p></div>` },
  'cash-in': { title:'Accept Payments', subtitle:'Terima pembayaran pelanggan menggunakan layanan DECA yang diaktifkan untuk merchant.', body:`<p>Dokumentasi integrasi DECA saat ini memuat tiga jalur penerimaan pembayaran. Pilih produk, ikuti urutan transaksi, lalu implementasikan endpoint dan callback yang tercantum pada spesifikasi.</p><div class="content-section"><h2>QRIS</h2><p>Buat QR dinamis, tampilkan QR kepada pelanggan, pantau status transaksi, lalu tangani notifikasi pembayaran. Referensi QRIS juga mencakup inquiry, refund, cancel, dan decode.</p>${linkRow('Panduan QRIS','docs/qris')} ${linkRow('Endpoint QRIS','reference/qris')}</div><div class="content-section"><h2>Virtual Account</h2><p>Buat nomor VA untuk transaksi, tampilkan instruksi pembayaran, lalu terima notifikasi saat pembayaran diproses. Masa berlaku dan jenis VA mengikuti konfigurasi pada kontrak produk.</p>${linkRow('Panduan Virtual Account','docs/virtual-account')} ${linkRow('Endpoint Virtual Account','reference/va')}</div><div class="content-section"><h2>External Checkout</h2><p>Buat checkout order melalui API Non-SNAP dan gunakan callback serta endpoint lookup yang tersedia untuk mengikuti status pembayaran.</p>${linkRow('Panduan External Checkout','docs/external-checkout')} ${linkRow('Endpoint External Checkout','reference/externalCheckout')}</div><div class="callout"><strong>Ketersediaan produk</strong><p>Produk dan kanal pembayaran perlu dikonfirmasi untuk akun merchant. Lihat API Reference untuk status dukungan dan batas kontrak yang tersedia.</p></div>` },
  qris: { title:'QRIS', subtitle:'Buat QR dinamis, pantau pembayaran, dan tangani perubahan status.', body:`<p>Alur QRIS menghubungkan sistem merchant dengan endpoint DECA untuk membuat transaksi dan menerima hasil pembayaran.</p><div class="content-section"><h2>Alur transaksi</h2><ol class="plain-steps"><li>Kirim permintaan pembuatan QR dengan referensi transaksi merchant dan jumlah pembayaran.</li><li>Tampilkan QR yang diterima kepada pelanggan untuk dipindai.</li><li>Terima notifikasi status melalui callback merchant.</li><li>Gunakan endpoint inquiry untuk memeriksa ulang transaksi jika diperlukan.</li></ol></div><div class="content-section"><h2>Operasi terkait</h2><p>Spesifikasi yang tersedia juga mencakup refund, cancel, dan QRIS decode. Kondisi penggunaan mengikuti kontrak endpoint dan status transaksi.</p>${linkRow('Lihat semua endpoint QRIS','reference/qris')}</div><div class="callout"><strong>Status transaksi QRIS</strong><p>Inquiry QRIS mencantumkan status transaksi <code>00</code> sampai <code>07</code>. Arti status ditampilkan pada response endpoint terkait; jangan memakai pemetaan ini untuk produk lain.</p>${linkRow('Buka endpoint status QRIS','reference/post-v-1-0-qr-qr-mpm-query')}</div>` },
  'virtual-account': { title:'Virtual Account', subtitle:'Buat VA, periksa status pembayaran, dan terima notifikasi dari DECA.', body:`<p>Integrasi Virtual Account menggunakan endpoint SNAP untuk pembuatan, inquiry, penghapusan, dan pemberitahuan pembayaran.</p><div class="content-section"><h2>Alur umum</h2><ol class="plain-steps"><li>Buat Virtual Account dengan data pelanggan, referensi transaksi, jumlah, dan waktu kedaluwarsa sesuai schema.</li><li>Tampilkan nomor VA serta detail pembayaran kepada pelanggan.</li><li>Terima callback pembayaran dan simpan hasilnya pada sistem merchant.</li><li>Gunakan inquiry atau operasi pengelolaan VA sesuai kebutuhan transaksi.</li></ol></div><div class="content-section"><h2>Endpoint Virtual Account</h2>${linkRow('Buka daftar endpoint VA','reference/va')}</div><div class="callout"><strong>Schema per endpoint</strong><p>Field create VA, inquiry, delete, dan callback berbeda. Ikuti contoh request serta response pada endpoint yang digunakan.</p></div>` },
  'external-checkout': { title:'External Checkout', subtitle:'Buat order pembayaran melalui API Non-SNAP DECA.', body:`<p>External Checkout menyediakan endpoint untuk membuat checkout order, mengambil order atau payment, dan menerima notifikasi. Implementasi memakai OAuth2 client credentials dan signature Non-SNAP sesuai dokumentasi DECA.</p><div class="content-section"><h2>Alur integrasi</h2><ol class="plain-steps"><li>Ambil access token OAuth2 menggunakan credential yang diberikan DECA.</li><li>Bentuk signature untuk request berdasarkan method, path, query, token, timestamp, dan body.</li><li>Buat checkout order dan simpan <code>reference_id</code> merchant.</li><li>Terima notifikasi perubahan status, lalu gunakan endpoint lookup untuk rekonsiliasi jika diperlukan.</li></ol></div><div class="content-section"><h2>Kontrak teknis</h2>${linkRow('Buka API Reference External Checkout','reference/externalCheckout')} ${linkRow('Baca panduan signature Non-SNAP','reference/nonsnapSignature')}</div><div class="callout"><strong>Contoh response lookup</strong><p>Dokumentasi DECA lama mencantumkan status HTTP untuk beberapa endpoint lookup tanpa schema body. Response body untuk bagian tersebut ditandai Coming Soon sampai DECA mengonfirmasi kontraknya.</p></div>` },
  'cash-out': { title:'Payouts', subtitle:'Kirim dana ke rekening bank atau akun e-money menggunakan layanan DECA.', body:`<p>Alur pencairan dana pada dokumentasi DECA terdiri dari transfer bank, top up e-money, dan pengiriman batch. Ketersediaan serta limit layanan ditentukan pada aktivasi merchant.</p><div class="content-section"><h2>Transfer bank</h2><p>Validasi rekening penerima melalui inquiry sebelum mengirim transfer. Pantau hasil melalui callback dan pencocokan status transaksi.</p>${linkRow('Panduan transfer bank','docs/bank-transfer')} ${linkRow('Endpoint transfer bank','reference/bankTransfer')}</div><div class="content-section"><h2>E-money Top Up</h2><p>Periksa akun tujuan, kirim permintaan top up, lalu gunakan endpoint inquiry status yang tersedia.</p>${linkRow('Panduan E-money Top Up','docs/ewallet-top-up')} ${linkRow('Endpoint E-money','reference/ewallet')}</div><div class="content-section"><h2>Batch disbursement</h2><p>Spesifikasi bulk menggunakan path SNAP <code>/out/</code>, sehingga dikelompokkan di sini sebagai pengiriman dana batch. Nama endpoint API resminya tetap dipertahankan.</p>${linkRow('Endpoint batch','reference/bulkCashIn')}</div>` },
  'bank-transfer': { title:'Transfer bank', subtitle:'Periksa rekening penerima sebelum mengirim dana dan menangani status transfer.', body:`<p>API transfer bank menyediakan langkah inquiry rekening, transaksi transfer, serta callback status untuk merchant.</p><div class="content-section"><h2>Urutan integrasi</h2><ol class="plain-steps"><li>Kirim inquiry dengan nomor rekening penerima dan data pelanggan yang dipersyaratkan.</li><li>Tampilkan nama rekening hasil inquiry untuk konfirmasi pada proses bisnis merchant.</li><li>Kirim permintaan transfer dengan referensi unik merchant dan kode bank yang sesuai.</li><li>Terima callback dan periksa kembali status jika dibutuhkan.</li></ol></div><div class="content-section"><h2>Endpoint</h2>${linkRow('Lihat API Reference transfer bank','reference/bankTransfer')}</div>` },
  'ewallet-top-up': { title:'E-money Top Up', subtitle:'Periksa akun tujuan, proses top up, dan pantau status transaksi.', body:`<p>API E-money mencakup account inquiry, customer top up, serta inquiry status top up.</p><div class="content-section"><h2>Urutan integrasi</h2><ol class="plain-steps"><li>Periksa nomor akun pelanggan dengan account inquiry.</li><li>Kirim permintaan top up sesuai skema request endpoint.</li><li>Gunakan inquiry status untuk mendapatkan informasi transaksi yang telah dikirim.</li></ol></div><div class="callout"><strong>Informasi provider</strong><p>Daftar provider, nominal yang didukung, biaya, dan limit transaksi tidak ditetapkan dalam referensi endpoint ini. Konfirmasikan cakupan layanan merchant kepada DECA.</p></div>${linkRow('Lihat API Reference E-money Top Up','reference/ewallet')}` },
  account: { title:'Account & Reports', subtitle:'Ambil informasi saldo dan rekening koran melalui endpoint akun.', body:`<p>Endpoint Account & Reports memberikan informasi saldo merchant dan data rekening koran. Keduanya merupakan alur operasional terpisah dari transaksi Cash In dan Payouts.</p><div class="content-section"><h2>Balance inquiry</h2><p>Gunakan balance inquiry untuk membaca informasi saldo akun sesuai akses merchant.</p>${linkRow('Endpoint Balance Inquiry','reference/post-v-1-0-balance-inquiry')}</div><div class="content-section"><h2>Bank statement</h2><p>Bank statement mengembalikan detail data transaksi dan informasi pagination sesuai response API.</p>${linkRow('Endpoint Bank Statement','reference/post-v-1-0-bank-statement')}</div>` },
  'authentication-guide': { title:'Authentication & security', subtitle:'Autentikasi berbeda antara endpoint SNAP dan Non-SNAP.', body:`<p>Gunakan skema yang sesuai dengan protokol endpoint. SNAP menggunakan B2B Access Token, header SNAP, dan signature. External Checkout Non-SNAP menggunakan OAuth2 client credentials dan signature Non-SNAP.</p><div class="content-section"><h2>SNAP</h2><p>Ambil B2B Access Token, lalu sertakan header yang diwajibkan pada request layanan.</p>${linkRow('Endpoint B2B Access Token','reference/auth')} ${linkRow('Request headers SNAP','reference/headers')}</div><div class="content-section"><h2>Non-SNAP</h2><p>Ambil access token melalui OAuth2 client credentials, lalu bentuk signature sesuai kontrak yang dipublikasikan DECA.</p>${linkRow('Endpoint OAuth2','reference/post-oauth-2-token')} ${linkRow('Panduan signature Non-SNAP','reference/nonsnapSignature')}</div><div class="callout"><strong>Jaga credential</strong><p>Simpan credential dan signing key di backend. Gunakan credential merchant dan environment masing-masing.</p></div>` },
  webhooks: { title:'Webhooks & payment notifications', subtitle:'Terima perubahan status transaksi dari DECA pada endpoint merchant.', body:`<p>DECA mengirim notifikasi ke URL callback yang disediakan dan didaftarkan oleh merchant. Callback QRIS, VA, bank transfer, batch, dan External Checkout memiliki schema masing-masing.</p><div class="content-section"><h2>Siapkan callback</h2><ol class="plain-steps"><li>Sediakan endpoint HTTPS server-side yang dapat menerima request DECA.</li><li>Validasi timestamp, signature, dan kontrak request sesuai produk serta protokol.</li><li>Simpan notifikasi dengan aman dan proses pembaruan status secara idempoten.</li><li>Kembalikan acknowledgement yang sesuai dengan schema callback.</li><li>Gunakan inquiry endpoint sebagai pemeriksaan status bila diperlukan.</li></ol></div><div class="content-section"><h2>Callback per layanan</h2><div class="link-list">${row('QRIS','QR MPM payment notification.','reference/post-webhook-qr-qr-mpm-notify')} ${row('Virtual Account','VA payment notification.','reference/post-webhook-transfer-va-payment')} ${row('Bank transfer','Transfer status notification.','reference/post-webhook-emoney-transfer-bank-notify')} ${row('Bulk','Batch status notification.','reference/post-webhook-emoney-bulk-cashin-notify')} ${row('External Checkout','Payment dan status notification Non-SNAP.','reference/externalCheckout')}</div></div><div class="callout"><strong>Jangan samakan semua payload</strong><p>Field dan acknowledgement mengikuti endpoint callback spesifik; lihat detail teknis sebelum memproses notifikasi.</p></div>` },
  testing: { title:'Testing & go-live', subtitle:'Validasi integrasi dan koordinasikan aktivasi production dengan DECA.', body:`<div class="content-section"><div class="section-label">STAGING</div><h2>Checklist pengujian</h2><ol class="plain-steps"><li>Pastikan base URL, credential, dan produk yang diuji telah diberikan untuk merchant.</li><li>Uji request sukses dan validasi input yang tidak sesuai pada tiap endpoint.</li><li>Uji callback dengan menyimpan referensi transaksi merchant dan reference dari DECA.</li><li>Periksa ulang status melalui inquiry endpoint bila tersedia, serta uji penanganan request duplikat sesuai response code.</li><li>Catat hasil uji dan kasus yang perlu dikonfirmasi kepada tim DECA.</li></ol></div><div class="content-section"><div class="section-label">PRODUCTION</div><h2>Aktivasi production</h2><p>Konfirmasikan hasil uji, kebutuhan verifikasi, base URL, produk yang aktif, dan credential production kepada tim DECA sebelum mulai mengirim transaksi nyata.</p>${linkRow('Lihat detail environment','docs/environments')}<p><a class="text-link" href="mailto:partnership@deca.co.id">partnership@deca.co.id ↗</a></p></div>` },
  faq: { title:'FAQ & troubleshooting', subtitle:'Langkah awal memeriksa kendala integrasi DECA.', body:`<div class="content-section"><h2>Request ditolak</h2><p>Periksa HTTP status dan responseCode pada body. Pastikan header, signature, format field, credential, dan path sesuai protokol serta environment.</p></div><div class="content-section"><h2>Status belum berubah</h2><p>Periksa callback yang diterima dan gunakan endpoint inquiry yang tersedia pada produk tersebut untuk mengonfirmasi status transaksi.</p></div><div class="content-section"><h2>Callback tidak tercatat</h2><p>Periksa endpoint HTTPS merchant, log request masuk, validasi signature, dan acknowledgement yang dikirimkan. Cocokkan dengan schema callback pada API Reference.</p></div><div class="content-section"><h2>Butuh bantuan integrasi?</h2><p>Kirim nama produk, environment, endpoint, waktu request, reference merchant, HTTP status, dan response code kepada tim DECA. Jangan sertakan secret atau private key.</p><a class="text-link" href="mailto:partnership@deca.co.id">Hubungi DECA ↗</a></div>` }
};


const referencePages = {
  home: { title:'API Reference', subtitle:'Spesifikasi endpoint DECA untuk integrasi pembayaran, pencairan, serta operasional akun.', body:`<p>Pilih produk untuk melihat method, path, service code, header, schema request/response, contoh payload, dan response code yang tersedia.</p><div class="callout"><strong>Sebelum mengirim request</strong><p>Pastikan akses merchant dan credential environment telah diberikan DECA. Contoh payload di referensi ini menggunakan data ilustratif.</p>${linkRow('Baca cara integrasi','docs/integration')} ${linkRow('Autentikasi & keamanan','reference/auth')}</div><div class="content-section"><div class="section-label">ACCEPT PAYMENTS</div><h2>Terima pembayaran</h2><div class="link-list">${row('QRIS','Generate, inquiry, refund, cancel, decode, dan callback.','reference/qris','SNAP')} ${row('Virtual Account','Create VA, inquiry, delete, dan payment notification.','reference/va','SNAP')} ${row('External Checkout','Create order, lookup payment/order, dan notification.','reference/externalCheckout','NON-SNAP')}</div></div><div class="content-section"><div class="section-label">PAYOUTS</div><h2>Kirim dana</h2><div class="link-list">${row('Bank Transfer','Inquiry rekening, transfer, dan status notification.','reference/bankTransfer','SNAP')} ${row('E-money Top Up','Account inquiry, top up, dan status inquiry.','reference/ewallet','SNAP')} ${row('Batch disbursement','Pengiriman batch melalui API bulk yang tersedia.','reference/bulkCashIn','SNAP')}</div></div><div class="content-section"><div class="section-label">ACCOUNT & REPORTS</div><h2>Operasional akun</h2><div class="link-list">${row('Balance & Bank Statement','Saldo dan riwayat transaksi akun.','reference/account','SNAP')}</div></div><div class="content-section"><div class="section-label">TECHNICAL GUIDES</div><h2>Authentication & request format</h2><div class="link-list">${row('B2B Access Token','Autentikasi SNAP.','reference/auth','SNAP')} ${row('OAuth2 Access Token','Autentikasi Non-SNAP.','reference/post-oauth-2-token','OAUTH2')} ${row('SNAP request headers','Header request layanan SNAP.','reference/headers')} ${row('Non-SNAP signature','Formula dan test vector DECA.','reference/nonsnapSignature')}</div></div><div class="content-section"><div class="section-label">COVERAGE</div><h2>Kontrak API yang tersedia</h2><p>Cash In, Payouts, inquiry saldo, rekening koran, token, signature, dan response code per endpoint telah dipetakan dari dokumentasi DECA sebelumnya. Field response yang belum tersedia pada sumber asal ditandai di halaman endpoint.</p></div><div class="content-section"><div class="section-label">DOKUMENTASI DALAM PENYUSUNAN</div><h2>Area API lainnya</h2>${comingSoonRow('Payment Link','API dan panduan merchant DECA belum tersedia.')} ${comingSoonRow('SDK & e-commerce plugins','Paket integrasi DECA belum tersedia.')} ${comingSoonRow('Wallet & sub-account','Kontrak API DECA belum tersedia.')}</div>` },
  qris: { title:endpointGroups.qris.title, subtitle:endpointGroups.qris.intro, group:'qris' },
  va: { title:endpointGroups.va.title, subtitle:endpointGroups.va.intro, group:'va' },
  bankTransfer: { title:endpointGroups.bankTransfer.title, subtitle:endpointGroups.bankTransfer.intro, group:'bankTransfer' },
  ewallet: { title:endpointGroups.ewallet.title, subtitle:endpointGroups.ewallet.intro, group:'ewallet' },
  bulkCashIn: { title:'Batch disbursement', subtitle:'Pengiriman batch mengikuti nama operation dan path resmi pada kontrak DECA.', group:'bulkCashIn' },
  account: { title:'Balance & Bank Statement', subtitle:endpointGroups.account.intro, group:'account' },
  auth: { title:'Authentication', subtitle:'Autentikasi SNAP dan endpoint untuk memperoleh access token.', body:`<p>Endpoint SNAP menggunakan B2B Access Token dan signature. External Checkout menggunakan OAuth2 client credentials dan signature Non-SNAP.</p>${endpointList(endpointGroups.auth.items)}<div class="content-section"><h2>Request headers SNAP</h2>${linkRow('Lihat headers SNAP','reference/headers')} ${linkRow('Panduan authentication','docs/authentication-guide')}</div><div class="content-section"><h2>Non-SNAP signature</h2>${linkRow('Baca formula dan test vector','reference/nonsnapSignature')}</div>` },
  headers: { title:'Request Headers', subtitle:'Header SNAP yang digunakan pada transaksi DECA.', body:`<p>Gunakan header berikut pada endpoint SNAP. Format timestamp dan signature mengikuti aturan kontrak DECA.</p>${fieldTable(snapHeaders,'Header','Keterangan')}` },
  externalCheckout: { title:'External Checkout', subtitle:'Referensi checkout pembayaran DECA menggunakan protokol Non-SNAP.', body:`<p>Kontrak ini mencakup pembuatan checkout order, pencarian order/payment, dan callback. Beberapa endpoint lookup pada dokumentasi lama hanya mencantumkan status HTTP; response body akan ditambahkan setelah tersedia.</p><div class="link-list">${externalRow('Create Checkout Order','POST','/nonSnapReference/generated/post-ec-v-1-copg-order','Membuat order checkout.')} ${externalRow('Get Checkout Order','GET','/nonSnapReference/generated/get-ec-v-1-copg-order-reference','Mengambil informasi checkout order.')} ${externalRow('Get Payment By ID','GET','/nonSnapReference/generated/get-ec-v-1-payment-id','Mengambil pembayaran berdasarkan ID.')} ${externalRow('Get Payment By Reference ID','GET','/nonSnapReference/generated/get-ec-v-1-payment-reference-id','Mengambil pembayaran berdasarkan reference.')} ${externalRow('Payment Status Changed Webhook','POST','/nonSnapReference/generated/post-webhook-ec-payment-status','Notifikasi perubahan status pembayaran.')} ${externalRow('External Checkout Payment Webhook','POST','/nonSnapReference/generated/post-webhook-ec-payment','Notifikasi pembayaran External Checkout.')}</div><div class="content-section"><h2>Authentication & signature</h2><p>Gunakan OAuth2 client credentials. Signature request menggunakan HMAC-SHA256 atas komponen yang ditentukan pada panduan Non-SNAP.</p>${linkRow('OAuth2 Access Token','reference/post-oauth-2-token')} ${linkRow('Panduan signature Non-SNAP','reference/nonsnapSignature')}</div>` }
};
referencePages.home.subtitle = 'Pilih SNAP atau Non-SNAP untuk membuka dokumentasi integrasi yang sesuai.';
referencePages.snapAuth = { title:'SNAP authentication', subtitle:'Autentikasi dan header untuk endpoint berprotokol SNAP.', body:`<p>Gunakan B2B Access Token untuk memanggil endpoint SNAP. Sertakan header dan signature SNAP sesuai kontrak DECA.</p>${endpointList([endpointGroups.auth.items[0]])}<div class="content-section"><h2>Request headers SNAP</h2><p>Header wajib mengikuti spesifikasi endpoint dan mengikutsertakan timestamp serta signature.</p>${linkRow('Lihat daftar request headers','reference/headers')}</div><div class="content-section"><h2>Endpoint SNAP</h2><div class="link-list">${row('QRIS','Generate, inquiry, refund, cancel, decode, dan callback.','reference/qris')} ${row('Virtual Account','Create VA, inquiry, delete, dan payment notification.','reference/va')} ${row('Payouts','Bank transfer, e-money top up, dan batch disbursement.','reference/bankTransfer')}</div></div>` };
referencePages.nonsnapAuth = { title:'Non-SNAP authentication', subtitle:'OAuth2 dan signature untuk integrasi External Checkout.', body:`<p>External Checkout memakai OAuth2 client credentials untuk memperoleh bearer token. Setiap request yang dilindungi juga harus ditandatangani dengan skema Non-SNAP.</p>${endpointList([endpointGroups.auth.items[1]])}<div class="content-section"><h2>Request signature</h2><p>Signature dihitung dengan HMAC-SHA256 menggunakan komponen request dan signing key yang sesuai.</p>${linkRow('Baca panduan Non-SNAP signature','reference/nonsnapSignature')}</div><div class="content-section"><h2>Produk Non-SNAP</h2>${linkRow('Buka API Reference External Checkout','reference/externalCheckout')}</div>` };
const endpointTitles = {};
const endpointOwners = {};
for (const [groupId, group] of Object.entries(endpointGroups)) {
  for (const [title,,docPath] of group.items) {
    const slug = docPath.split('/').pop();
    endpointTitles[slug] = title;
    endpointOwners[slug] = groupId;
  }
}
